ProgramBlock.ScriptSetup:
Program.Setup(() => {
  Program
    .AddOption("Title", "", "1. Dashboard title", "text")
    .AddOption("Subtitle", "", "2. Dashboard subtitle", "text")
    .AddOption("RoadSpeed", "very-slow", "3. Road speed", "select:HOMEGENIE.neon_district_road_speed_very_slow=very-slow,HOMEGENIE.neon_district_road_speed_slow=slow,HOMEGENIE.neon_district_road_speed_normal=normal")
    .AddOption("Message", "", "4. District message", "text")
    .AddOption("DisableAnimations", "false", "5. Disable animations", "checkbox");
  Program.Parameter("Dashboard.Theme.Cyberpunk").Value = "";
});
Program.Run();

ProgramBlock.ScriptSource:
var optionNames = new[] { "Title", "Subtitle", "RoadSpeed", "Message" };
const string optionPrefix = "ConfigureOptions.";
const string fieldPrefix = "Dashboard.NeonDistrict.";

When.ModuleParameterChanged((module, property) => {
  if (module.Instance == Program.Module && property.Name.StartsWith(optionPrefix, StringComparison.Ordinal))
  {
    var name = property.Name.Substring(optionPrefix.Length);
    if (name == "DisableAnimations")
      Program.Emit("Dashboard.AnimationsDisabled", property.Value);
    else if (Array.IndexOf(optionNames, name) >= 0)
      Program.Emit(fieldPrefix + name, property.Value);
  }
  return true;
});

Program.Emit("Dashboard.Theme.Cyberpunk", "");
foreach (var name in optionNames)
  Program.Emit(fieldPrefix + name, Program.Option(name).Value);

Program.Emit("Dashboard.AnimationsDisabled", Program.Option("DisableAnimations").Value);
Program.GoBackground();

ProgramBlock.ScriptSetup:
Program.Setup(() => {
  Program
    .AddOption("Eyebrow", "", "1. Text above the title", "text")
    .AddOption("Title", "", "2. Dashboard title", "text")
    .AddOption("Subtitle", "", "3. Dashboard subtitle", "text")
    .AddOption("DisableAnimations", "false", "4. Disable animations", "checkbox");
  Program.Parameter("Dashboard.Theme.Isometric").Value = "";
});
Program.Run();

ProgramBlock.ScriptSource:
var headings = new[] { "Eyebrow", "Title", "Subtitle" };
const string optionPrefix = "ConfigureOptions.";
const string headingPrefix = "Dashboard.Isometric.";

When.ModuleParameterChanged((module, property) => {
  if (module.Instance == Program.Module && property.Name.StartsWith(optionPrefix, StringComparison.Ordinal))
  {
    var name = property.Name.Substring(optionPrefix.Length);
    if (name == "DisableAnimations")
      Program.Emit("Dashboard.AnimationsDisabled", property.Value);
    else if (Array.IndexOf(headings, name) >= 0)
      Program.Emit(headingPrefix + name, property.Value);
  }
  return true;
});

Program.Emit("Dashboard.Theme.Isometric", "");
foreach (var name in headings)
  Program.Emit(headingPrefix + name, Program.Option(name).Value);
Program.Emit("Dashboard.AnimationsDisabled", Program.Option("DisableAnimations").Value);
Program.GoBackground();
